const I={shield:'M12 3 20 6v6c0 5-5 8-8 10-3-2-8-5-8-10V6Z|m8 12 3 3 5-6',grid:'M3 3h7v7H3z|M14 3h7v7h-7z|M3 14h7v7H3z|M14 14h7v7h-7z',devices:'M4 4h16v11H4z|M9 20h6|M12 15v5',map:'M10 3h4v4h-4z|M3 17h5v4H3z|M16 17h5v4h-5z|M12 7v5|M5.5 17v-5h13v5',history:'M3 11a9 9 0 1 1 2.8 7|M3 4v7h7|M12 7v5l3 2',book:'M3 4h6c2 0 3 1 3 2 0-1 1-2 3-2h6v15h-6c-2 0-3 1-3 2-1-1-2-2-4-2H3Z|M12 6v15',settings:'M9 3h6l1 3 3 1 2 5-2 3-1 4-5 2-3-2-4-1-2-5 2-3 1-4Z|M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',arrow:'M4 12h16|m14 6 6 6-6 6',download:'M12 3v12|m7 10 5 5 5-5|M5 17v4h14v-4',scan:'M4 9V4h5|M15 4h5v5|M20 15v5h-5|M9 20H4v-5|M8 12h8|M12 8v8',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15|m16 16 5 5',wifi:'M2 8a16 16 0 0 1 20 0|M5 12a11 11 0 0 1 14 0|M8 16a6 6 0 0 1 8 0|M12 20h.01',router:'M4 13h16v7H4z|M7 13V6|M17 13V4|M8 17h.01|M12 17h.01|M16 17h.01',laptop:'M5 4h14v12H5z|M2 19h20l-3-3H5Z',tv:'M3 6h18v13H3z|m8 2 4 4 4-4|M8 22h8',phone:'M7 2h10v20H7z|M11 18h2',printer:'M6 8V3h12v5|M6 17H3V9h18v8h-3|M6 14h12v8H6z|M17 11h.01',database:'M4 6c0-5 16-5 16 0s-16 5-16 0v12c0 5 16 5 16 0V6|M4 12c0 5 16 5 16 0',speaker:'M6 2h12v20H6z|M9 15a3 3 0 1 0 6 0 3 3 0 0 0-6 0|M12 6h.01',port:'M4 7h16v10H4z|M8 10v4|M12 10v4|M16 10v4|M7 4v3|M17 4v3|M7 17v3|M17 17v3',alert:'M12 3 22 21H2Z|M12 9v5|M12 17h.01',chart:'M4 3v17h17|M8 15l4-5 4 3 5-7',check:'m5 12 4 4 10-10',lock:'M5 10h14v11H5z|M8 10V6a4 4 0 0 1 8 0v4|M12 14v3',unlock:'M5 10h14v11H5z|M8 10V6a4 4 0 0 1 7-3|M12 14v3',trophy:'M7 3h10v7c0 7-10 7-10 0Z|M7 5H3v3c0 4 4 4 4 4|M17 5h4v3c0 4-4 4-4 4|M12 15v6|M8 21h8',spark:'m12 2 2 7 7 3-7 2-2 7-3-7-7-2 7-3Z',leaf:'M20 3c-11-1-18 10-11 15s13-5 11-15Z|M5 22 15 10',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5Z|M10 21h4',close:'m6 6 12 12|M18 6 6 18',expand:'M8 3H3v5|M16 3h5v5|M3 16v5h5|M21 16v5h-5',menu:'M4 6h16|M4 12h16|M4 18h16',sun:'M8 12a4 4 0 1 0 8 0 4 4 0 0 0-8 0|M12 2v2|M12 20v2|M2 12h2|M20 12h2|m5 5 1 1|m18 18 1 1|m5 19 1-1|m18 6 1-1',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',globe:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0|M3 12h18|M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',file:'M5 2h9l5 5v15H5Z|M14 2v6h5|M8 12h8|M8 16h8',sheet:'M4 3h16v18H4z|M4 9h16|M4 15h16|M10 3v18',edit:'m15 3 6 6-12 12H3v-6Z|m12 6 6 6',info:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0|M12 11v6|M12 7h.01',help:'M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0|M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.6v.6|M12 17h.01',camera:'M3 7h4l2-3h6l2 3h4v13H3z|M9 13a3 3 0 1 0 6 0 3 3 0 0 0-6 0',game:'M6 9h12a4 4 0 0 1 0 8c-2 0-3-2-6-2s-4 2-6 2a4 4 0 0 1 0-8Z|M8 11v4|M6 13h4|M16 12h.01|M18 14h.01',trash:'M4 7h16|M9 7V4h6v3|M6 7l1 14h10l1-14'};
const TYPE_ICON={computer:'devices',laptop:'laptop',phone:'phone',tablet:'phone',tv:'tv',media:'tv',speaker:'speaker',printer:'printer',storage:'database',router:'router',camera:'camera',iot:'spark',game:'game',other:'help',unknown:'help'};
const DEVICE_TYPES=['computer','laptop','phone','tablet','tv','media','speaker','printer','storage','router','camera','iot','game','other'];
const UNCERTAIN=['filtered','no_response','open_filtered','not_tested','error'];

let state={token:null,lang:'en',theme:'light',tips:true,retention:'180',defaultProfile:'quick',view:'overview',filter:'all',query:'',guideQuery:'',menu:false,
  caps:null,interfaces:[],dash:null,rules:{},rulesList:[],guide:{faq:[],tips:[]},tipIndex:0,active:null,sse:null,
  scanForm:null,history:{items:[],total:0,page:1,scopes:[],scope:'',from:'',to:''},device:null,report:{format:'pdf',lang:null,scanId:null},fatal:false,booted:false};
let toastTimer=null;
try{const th=localStorage.getItem('lanora-theme');if(th==='dark'||th==='light')state.theme=th;}catch{}

function t(k,p={}){const v=(M[k]||[k,k,k])[LANGS.indexOf(state.lang)]??k;return v.replace(/\{(\w+)\}/g,(_,key)=>p[key]??'');}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function icon(name,size=18,cls=''){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" class="icon ${cls}" aria-hidden="true">${(I[name]||I.shield).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`;}
function locale(){return state.lang==='tr'?'tr-TR':state.lang==='de'?'de-DE':'en-GB';}
function dateText(iso){return iso?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',year:'numeric'}).format(new Date(iso)):'—';}
function timeText(iso){return iso?new Intl.DateTimeFormat(locale(),{hour:'2-digit',minute:'2-digit'}).format(new Date(iso)):'';}
function num(n){return new Intl.NumberFormat(locale()).format(n);}
function pct(x){return x==null?'—':new Intl.NumberFormat(locale(),{style:'percent',maximumFractionDigits:0}).format(x);}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4800);}
function errText(e){const k='err_'+(e?.code||'');return M[k]?t(k,e.details||{}):t('err_generic',{code:e?.code||e?.message||'?'});}
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
function stateLabel(s){return M[s]?t(s):s;}
function reasonLabel(r){return r?(M['r_'+r]?t('r_'+r):r):'';}

/* ---------- API ---------- */
async function api(method,path,body,opts={}){
  const headers={'Authorization':'Bearer '+state.token};
  if(method!=='GET')headers['Content-Type']='application/json';
  if(opts.idem)headers['Idempotency-Key']=opts.idem;
  const r=await fetch('/api/v1'+path,{method,headers,body:method==='GET'?undefined:JSON.stringify(body||{}),cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});
  if(r.status===401){sessionLost();throw Object.assign(new Error('SESSION_INVALID'),{code:'SESSION_INVALID'});}
  if(opts.raw){if(!r.ok)throw await toError(r);return r;}
  const data=(r.headers.get('content-type')||'').includes('json')?await r.json():null;
  if(!r.ok)throw Object.assign(new Error(data?.code||'HTTP_'+r.status),{code:data?.code,status:r.status,details:data?.details});
  return data;
}
async function toError(r){let d=null;try{d=await r.json();}catch{}return Object.assign(new Error(d?.code||'HTTP_'+r.status),{code:d?.code,status:r.status,details:d?.details});}
function sessionLost(){if(state.fatal)return;state.fatal=true;state.token=null;if(state.sse){state.sse.ctrl.abort();state.sse=null;}renderFatal();}

/* ---------- Bootstrap ---------- */
async function boot(){
  document.body.dataset.theme=state.theme;
  const nav=(navigator.language||'en').slice(0,2);state.lang=LANGS.includes(nav)?nav:'en';
  document.getElementById('app').innerHTML=`<div class="loading">${t('loading')}</div>`;
  const m=/[#&]k=([A-Za-z0-9_-]{43})(?:&|$)/.exec(location.hash||'');
  history.replaceState(null,'',location.pathname);
  if(!m){renderFatal();return;}
  try{
    const r=await fetch('/api/v1/session/bootstrap',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({secret:m[1]}),cache:'no-store',credentials:'omit'});
    if(!r.ok)throw new Error('bootstrap');
    state.token=(await r.json()).token;
  }catch{renderFatal();return;}
  const [settings,caps,ifs]=await Promise.all([api('GET','/settings'),api('GET','/capabilities'),api('GET','/network-interfaces')]);
  applySettings(settings);state.caps=caps;state.interfaces=ifs.items;
  await Promise.all([loadLangContent(),loadDashboard()]);
  state.tipIndex=Math.floor(Math.random()*Math.max(1,state.guide.tips.length));
  state.booted=true;render();
  if(state.dash?.active)subscribe(state.dash.active.scan_id);
}
function applySettings(s){state.lang=s.lang;state.theme=s.theme;state.tips=s.tips;state.retention=s.retention;state.defaultProfile=s.default_profile;try{localStorage.setItem('lanora-theme',state.theme);}catch{}}
async function loadLangContent(){
  const [g,r]=await Promise.all([api('GET','/guide?lang='+state.lang),api('GET','/rules?lang='+state.lang)]);
  state.guide=g;state.rulesList=r.rules;state.rules=Object.fromEntries(r.rules.map(x=>[x.id,x]));
}
async function loadDashboard(){state.dash=await api('GET','/dashboard');if(state.dash.active&&!state.active)state.active=state.dash.active;}
async function saveSettings(patch){const s=await api('PATCH','/settings',patch);applySettings(s);}
function renderFatal(){document.body.dataset.theme=state.theme;document.getElementById('app').innerHTML=`<div class="fatal"><div class="card"><span style="color:var(--green)">${icon('shield',40)}</span><h1>${t('sessionTitle')}</h1><p>${t('sessionText')}</p></div></div>`;for(const id of ['modal','device-panel']){const d=document.getElementById(id);if(d.open)d.close();}}

/* ---------- Event stream (SSE via fetch with Authorization header) ---------- */
async function subscribe(scanId){
  if(state.sse?.id===scanId)return;
  if(state.sse)state.sse.ctrl.abort();
  const s={id:scanId,ctrl:new AbortController(),last:0,finished:false};state.sse=s;
  while(state.sse===s&&!s.finished){
    try{
      const r=await fetch(`/api/v1/scans/${encodeURIComponent(scanId)}/events`,{headers:{'Authorization':'Bearer '+state.token,'Last-Event-ID':String(s.last)},signal:s.ctrl.signal,cache:'no-store',credentials:'omit'});
      if(r.status===401){sessionLost();return;}
      if(!r.ok)throw new Error('sse');
      const reader=r.body.pipeThrough(new TextDecoderStream()).getReader();let buf='';
      for(;;){const {value,done}=await reader.read();if(done)break;buf+=value.replace(/\r/g,'');let i;
        while((i=buf.indexOf('\n\n'))>=0){const chunk=buf.slice(0,i);buf=buf.slice(i+2);handleEvent(chunk,s);}}
    }catch(e){if(s.ctrl.signal.aborted)return;}
    if(!s.finished)await sleep(1000);
  }
}
function handleEvent(chunk,s){
  let type='message',data='',id=null;
  for(const line of chunk.split('\n')){if(line.startsWith(':'))continue;const c=line.indexOf(':');const f=c<0?line:line.slice(0,c);const v=c<0?'':line.slice(c+1).replace(/^ /,'');
    if(f==='event')type=v;else if(f==='data')data+=(data?'\n':'')+v;else if(f==='id')id=Number(v);}
  if(id)s.last=id;
  let payload=null;try{payload=data?JSON.parse(data):null;}catch{return;}
  switch(type){
    case'snapshot':case'progress':case'resync':state.active=payload;updateBanner();break;
    case'phase_changed':state.active=payload;render();break;
    case'scan_finished':s.finished=true;state.sse=null;state.active=null;onScanFinished(payload);break;
  }
}
async function onScanFinished(p){
  const sum=p?.summary;
  if(p?.state==='completed')toast(t('scanDone',{hosts:sum?.hosts_responded??0,prio:sum?.priority_findings??0}));
  else toast(t('scanEnded',{state:stateLabel(p?.state)+(p?.reason_code?' · '+reasonLabel(p.reason_code):'')}));
  try{await loadDashboard();if(state.view==='history')await loadHistory(true);}catch{}
  render();
}

/* ---------- View model ---------- */
function hostName(h){return h.label||(h.is_local?t('thisDevice'):h.is_gateway?t('gatewayName'):h.vendor?t('deviceOf',{v:shortVendor(h.vendor)}):t('unknownDevice'));}
function shortVendor(v){return String(v).replace(/,?\s+(Inc|Ltd|LLC|Co|Corp|Corporation|GmbH|AG|S\.A|Technologies|Technology|Electronics|International|Limited)\.?.*$/i,'').slice(0,40);}
function hostType(h){return h.user_type||h.type_guess||'unknown';}
function hostIcon(h){return TYPE_ICON[hostType(h)]||'help';}
function prioFindings(h){return (h.findings||[]).filter(f=>f.severity==='high'||f.severity==='medium');}
function level(h){const f=h.findings||[];if(f.some(x=>x.severity==='high'))return'high';if(f.some(x=>x.severity==='medium'))return'medium';if((h.open||[]).length)return'info';return h.coverage>=0.7?'ok':'unknown';}
function riskChip(h){const l=level(h);const map={high:['high','high','alert'],medium:['medium','medium','alert'],info:['','informational','info'],ok:['ok','noOpenObserved','check'],unknown:['unknown','uncertainState','help']};const [cls,k,ic]=map[l];return `<span class="risk-chip ${cls}">${icon(ic,11)}${t(k)}</span>`;}
function hosts(){return state.dash?.hosts||[];}
function scan(){return state.dash?.scan||null;}
function allPrio(){return hosts().flatMap(h=>prioFindings(h).map(f=>({h,f}))).sort((a,b)=>b.f.penalty-a.f.penalty||a.f.port-b.f.port);}
function centerHost(){return hosts().find(h=>h.is_gateway)||hosts().find(h=>h.is_local)||null;}

/* ---------- Components ---------- */
function scanBanner(){
  const a=state.active;if(!a)return '';
  const advanced=a.engine==='advanced';
  const title=advanced
    ? `${t(a.state==='cancelling'?'cancelling':'scanningAdvanced')}${a.phase_label?' · '+esc(a.phase_label):''}`
    : `${t(a.state==='cancelling'?'cancelling':'scanning')} · ${t('phaseOf',{i:a.phase_index||1,n:a.phase_count||5})} · ${t('phase_'+(a.phase||'discovery'))}`;
  const detail=advanced
    ? t('progressAdvanced',{hosts:a.hosts_responded||0})
    : t('progressDetail',{done:num(a.phase_done||0),total:num(a.phase_total||0),hosts:a.hosts_responded||0});
  return `<div class="running-banner" id="scan-banner" role="status" aria-live="polite">${icon('scan',23,'spin')}<div class="running-info"><div class="running-title">${title}</div><div class="running-track"><span style="width:${a.phase_percent||0}%"></span></div><div class="field-hint">${detail}</div></div><span class="running-percent">${a.phase_percent||0}%</span><button class="btn btn-secondary" data-action="stop-scan" ${a.state==='cancelling'?'disabled':''}>${t('stopScan')}</button></div>`;
}
function updateBanner(){const el=document.getElementById('scan-banner');if(el&&state.active){el.outerHTML=scanBanner();}else if(state.booted&&!document.getElementById('modal').open)render();}
function actions(){return `<div class="heading-actions"><button class="btn btn-secondary" data-action="report" ${scan()?'':'disabled'}>${icon('download',15)}${t('downloadReport')}</button><button class="btn btn-primary" data-action="scan" ${state.active||state.caps?.scanning_available===false?'disabled':''}>${icon('scan',16)}${t('startScan')}</button></div>`;}
function heading(title,sub,eyebrow=false){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${t('eyebrow')}</div>`:''}<h1>${title}</h1><p class="subtitle">${sub}</p></div>${actions()}</div>`;}
function notices(){
  const s=scan(),o=state.dash?.latest_other;let html='';
  if(s&&s.state!=='completed')html+=`<div class="detail-callout warn" style="margin-top:0">${icon('info',14)} ${t('partialNote',{reason:reasonLabel(s.reason_code)||stateLabel(s.state)})}</div>`;
  if(o&&!['running','queued','cancelling'].includes(o.state)&&s&&o.started_at>s.started_at)html+=`<div class="info-box" style="margin:0 0 18px">${icon('info',13)} ${t('olderResultNote',{state:stateLabel(o.state)})}</div>`;
  return html;
}
function scoreCard(){
  const s=scan();const prio=allPrio();const high=prio.some(x=>x.f.severity==='high');
  let value='—',small=t('outOf'),na=true,statusCls='unknown',statusText=t('notEvaluable'),desc=t('emptyText');
  if(s){
    if(s.network_state==='ok'&&s.network_score!=null){value=String(s.network_score);na=false;small=t('outOf')+(s.provisional?' · '+t('provisional'):'');}
    else{small=s.network_state==='insufficient_coverage'?t('insufficient'):t('notEvaluable');}
    statusCls=high?'high':prio.length?'medium':'ok';statusText=high?t('reviewNeeded'):prio.length?t('reviewSuggested'):t('noPriorityStatus');
    desc=prio.length?t('scoreDescription',{n:prio.length}):s.network_state==='ok'?t('scoreNoFinding'):t('scoreInsufficient');
    if(prio.length&&s.network_state!=='ok')desc+=' '+t('scoreInsufficient');
  }
  const offset=na?365:365*(1-(s.network_score/100));
  const scope=s?`<p class="scope-line">${icon('info',11)}<span>${t('scopeBasis',{profile:t(s.profile_id),ports:s.port_count,cov:s.coverage==null?'—':Math.round(s.coverage*100)})}</span></p>`:'';
  return `<section class="card score-card"><div class="card-label">${t('scoreLabel')}<span class="info-dot" title="${esc(t('scoreHelp'))}" tabindex="0" aria-label="${esc(t('scoreHelp'))}">i</span></div><div class="score-content"><div class="score-gauge" role="img" aria-label="${esc(t('scoreLabel'))}: ${na?esc(small):value+' / 100'}"><svg viewBox="0 0 140 140" aria-hidden="true"><circle class="gauge-track" cx="70" cy="70" r="58"/><circle class="gauge-progress" cx="70" cy="70" r="58" style="stroke-dashoffset:${offset}"/></svg><div class="gauge-value"><strong class="${na?'na':''}">${value}</strong><small>${esc(small)}</small></div></div><div class="score-copy"><div class="score-status ${statusCls}"><span class="status-dot"></span>${statusText}</div><h2>${t(s?'scoreHeadline':'emptyTitle')}</h2><p>${desc}</p>${s?(prio.length?`<button class="text-button score-link" data-action="view-findings">${t('viewFindings')}${icon('arrow',13)}</button>`:''):`<button class="text-button score-link" data-action="scan">${t('startScan')}${icon('arrow',13)}</button>`}</div></div>${scope}</section>`;
}
function networkVisual(limit){
  const center=centerHost();const others=hosts().filter(h=>h!==center);const shown=others.slice(0,limit);const n=shown.length;
  const pts=shown.map((_,j)=>{const a=(-90+(360/Math.max(n,1))*j)*Math.PI/180;return [50+40*Math.cos(a),47+38*Math.sin(a)];});
  const cls=h=>{const l=level(h);return l==='high'?'risky':l==='medium'?'medium':l==='unknown'?'unknown':'';};
  const cidr=scan()?.network_cidr||(state.interfaces.find(a=>a.selectable)?.network_cidr??'');
  return `<div class="network-visual"><svg class="network-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${center?pts.map(([x,y])=>`<path d="M50 47 Q${(50+x)/2} ${(47+y)/2-4} ${x} ${y}" vector-effect="non-scaling-stroke"/>`).join(''):''}</svg>${shown.map((h,j)=>`<button class="net-node ${cls(h)}" style="left:${pts[j][0]}%;top:${pts[j][1]}%" data-host="${h.id}" title="${esc(hostName(h))} · ${esc(h.ip)}" aria-label="${esc(hostName(h))} · ${esc(h.ip)}">${icon(hostIcon(h),19)}</button>`).join('')}${center?`<button class="net-node central ${cls(center)}" style="left:50%;top:47%" data-host="${center.id}" aria-label="${esc(hostName(center))}">${icon(hostIcon(center),27)}</button><div class="net-label"><strong>${esc(hostName(center))}</strong><br>${esc(center.ip)}</div>`:''}${others.length>limit?`<span class="net-more">${t('moreDevices',{n:others.length-limit})}</span>`:''}<div class="net-corner">${icon('wifi',12)}${esc(cidr)}</div></div>`;
}
function metrics(){
  const s=scan();const open=hosts().reduce((n,h)=>n+(h.open||[]).length,0);const prio=allPrio().length;
  const help=s?t('coverageHelp',{done:num(s.definite_pairs),total:num(s.planned_pairs)}):'';
  const items=[['devices',s?s.hosts_responded:'—','deviceCount',s?t('probedNote',{probed:s.addresses_probed}):''],['port',s?open:'—','openPorts',''],['alert',s?prio:'—','priorityFindings',''],['chart',s?pct(s.coverage):'—','coverage','']];
  return `<div class="metrics">${items.map(([i,v,k,note])=>`<div class="card metric" ${k==='coverage'&&help?`title="${esc(help)}"`:''}><div class="metric-icon">${icon(i,21)}</div><div><div class="metric-label">${t(k)}</div><div class="metric-value">${v}</div></div>${note?`<span class="metric-note">${esc(note)}</span>`:''}</div>`).join('')}</div>`;
}
function visibleHosts(){const q=state.query.toLocaleLowerCase(locale());return hosts().filter(h=>{const p=prioFindings(h).length>0;return (state.filter!=='priority'||p)&&(state.filter!=='normal'||!p)&&(!q||(hostName(h)+' '+h.ip+' '+(h.vendor||'')+' '+(h.mac||'')).toLocaleLowerCase(locale()).includes(q));});}
function lastScanLabel(){const s=scan();return s?t('latestScan',{date:dateText(s.started_at),time:timeText(s.started_at)}):'';}
function devicesTable(full=false){
  const ds=visibleHosts();
  return `<section class="card devices-card"><div class="card-header"><h2 class="card-title">${t('devices')}<span class="count-badge">${hosts().length}</span></h2>${!full?`<button class="text-button" data-view="devices">${t('seeAll')}${icon('arrow',13)}</button>`:''}</div><div class="table-toolbar"><div class="filters" role="group" aria-label="${t('status')}">${[['all','all'],['priority','priority'],['normal','normal']].map(([v,k])=>`<button class="filter ${state.filter===v?'selected':''}" data-filter="${v}" aria-pressed="${state.filter===v}">${t(k)}${v==='all'?` <span>${hosts().length}</span>`:''}</button>`).join('')}</div><label class="search">${icon('search',14)}<input id="device-search" placeholder="${t('searchDevice')}" aria-label="${t('searchDevice')}" value="${esc(state.query)}"></label></div><div class="table-scroll"><table class="device-table"><thead><tr><th>${t('device')}</th><th>${t('ipAddress')}</th><th>${t('openPorts')}</th><th>${t('status')}</th><th><span class="sr-only"></span></th></tr></thead><tbody>${ds.map(h=>`<tr data-host="${h.id}"><td><div class="device-id"><div class="device-icon">${icon(hostIcon(h),18)}</div><div><div class="device-name">${esc(hostName(h))}</div><div class="device-meta">${esc(h.vendor?shortVendor(h.vendor):t('unknown'))} · ${t('type_'+hostType(h))}</div></div></div></td><td><span class="ip">${esc(h.ip)}</span></td><td><div class="port-chips">${(h.open||[]).slice(0,2).map(p=>`<span class="port-chip">${p.port}</span>`).join('')}${(h.open||[]).length>2?`<span class="port-chip">+${h.open.length-2}</span>`:''}${!(h.open||[]).length?'<span class="port-chip">—</span>':''}</div></td><td>${riskChip(h)}</td><td><button class="table-open" data-host="${h.id}" aria-label="${esc(hostName(h))} — ${t('review')}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table>${ds.length?'':`<div class="empty-state">${hosts().length?t('noResults'):t('emptyText')}</div>`}</div><div class="table-foot"><span>${t('showing',{n:ds.length})}</span><span>${lastScanLabel()}</span></div></section>`;
}
function findingsCard(){
  const items=allPrio().slice(0,5);
  return `<section class="card findings-card" id="findings-card"><div class="finding-heading">${icon('alert',17)}<h2 class="card-title">${t('lookHere')}</h2></div><p class="small">${items.length?t('findingsSub'):(scan()?t('noFindingsCard'):t('emptyText'))}</p><div class="finding-list">${items.map(({h,f})=>`<button class="finding" data-host="${h.id}" data-tab="ports"><span class="finding-icon" style="${f.severity==='medium'?'background:#f7efdc;color:#94691c':''}">${icon(f.severity==='high'?'unlock':'info',15)}</span><span><span class="finding-title" style="display:block">${f.port} · ${esc(state.rules[f.rule_id]?.title||f.rule_id)}</span><span class="finding-desc">${esc(hostName(h))} · ${esc(h.ip)} · ${t(f.severity)}</span></span><span class="finding-chevron">${icon('chevron',12)}</span></button>`).join('')}</div></section>`;
}
function guideCard(){const tip=state.guide.tips[state.tipIndex]||'';return `<section class="card guide-card">${icon('leaf',26)}<div class="guide-tag">${t('quickLearn')}</div><h3>${t('guideQuestion')}</h3><p>${t('guideTeaser')}</p><button class="text-button" data-action="learn-port">${t('learnMinute')}${icon('arrow',13)}</button>${tip?`<div class="guide-tag" style="margin-top:16px">${t('tipLabel')}</div><p style="margin-top:0">${esc(tip)}</p><button class="text-button" data-action="next-tip">${t('nextTip')}${icon('arrow',13)}</button>`:''}</section>`;}
function badgeList(){
  const b=Object.fromEntries((state.dash?.badges||[]).map(x=>[x.badge_key,x]));
  return [['spark','first_scan','firstScan','firstScanNote'],['shield','network_guardian','guardian','guardianNote'],['lock','no_priority_findings','noPriority','noPriorityNote']].map(([i,key,k,n])=>({i,key,k,n,b:b[key]||{earned:false,active:false}}));
}
function badgeNote(x){if(x.b.earned&&!x.b.active)return t('badgeInactive');if(x.b.earned)return t('earnedOn',{date:dateText(x.b.awarded_at)});if(x.key==='network_guardian')return t('guardianNote')+' ('+t('journeyProgress',{n:x.b.progress||0})+')';return t(x.n);}
function badges(){return `<section class="achievements"><div class="achievement-header"><h2 class="card-title">${t('achievements')}</h2><span style="font-size:10px;color:var(--muted)">${t('progressMatters')}</span></div><div class="badge-row">${badgeList().map(x=>`<button class="card badge-item ${x.b.earned?(x.b.active?'':'inactive'):'locked'}" data-action="badges" style="text-align:left"><span class="badge-icon">${icon(x.i,23)}</span><span><span class="badge-name" style="display:block">${t(x.k)}</span><span class="badge-note">${esc(badgeNote(x))}</span></span>${x.b.earned&&x.b.active?`<span class="badge-check">${icon('check',13)}</span>`:''}</button>`).join('')}</div></section>`;}

/* ---------- Sayfalar ---------- */
function overview(){return `${heading(t('hello'),t('helloSub'),true)}${scanBanner()}${notices()}<div class="hero-grid">${scoreCard()}<section class="card network-card"><div class="network-top"><h2 class="card-label">${t('networkView')}</h2><span class="network-chip"><span class="status-dot"></span>${esc(t('kind_'+(scan()?.interface_kind||'other')))}</span></div>${networkVisual(7)}<button class="icon-button net-expand" data-view="map" aria-label="${t('expand')}">${icon('expand',15)}</button></section></div>${metrics()}<div class="content-grid">${devicesTable()}<aside class="aside-stack">${findingsCard()}${state.tips?guideCard():''}</aside></div>${badges()}`;}
function devicesView(){return `${heading(t('devices'),t('devicesSub'))}${scanBanner()}${notices()}${metrics()}${devicesTable(true)}`;}
function mapView(){return `${heading(t('map'),t('mapSub'))}${scanBanner()}<section class="card section-panel"><div class="network-top"><h2 class="card-title">${esc(scan()?.network_cidr||t('map'))}<span class="count-badge">${hosts().length} ${t('devices').toLocaleLowerCase(locale())}</span></h2><span class="network-chip"><span class="status-dot"></span>${esc(scan()?.gateway||'')}</span></div><div class="card wide-map">${networkVisual(30)}</div><div class="map-legend"><span><i class="status-dot"></i>${t('mapLegendNormal')}</span><span><i class="status-dot risk"></i>${t('mapLegendPriority')}</span><span><i class="status-dot" style="background:#b8c0bb"></i>${t('mapLegendUnknown')}</span></div><p class="subtitle" style="text-align:center;margin-top:20px">${t('mapNote')}</p></section>`;}
function chart(){
  const items=state.history.items.filter(h=>h.state==='completed').slice(0,12).reverse();
  if(!items.length)return `<div class="empty-state">${t('noScans')}</div>`;
  const W=500,H=150,n=items.length;const x=j=>n===1?W/2:10+j*(W-20)/(n-1);const y=v=>10+(100-v)*1.3;
  const pts=items.map((h,j)=>h.network_score==null?null:[x(j),y(h.network_score)]);
  let path='';pts.forEach((p,j)=>{if(!p)return;path+=(j===0||!pts[j-1]?'M':'L')+p[0].toFixed(1)+' '+p[1].toFixed(1)+' ';});
  return `<svg class="history-chart" viewBox="0 0 ${W} ${H+5}" role="img" aria-label="${esc(items.map(h=>h.network_score??'—').join(', '))}">${[10,75,140].map(yy=>`<path d="M0 ${yy}H${W}" stroke="var(--line)" stroke-dasharray="3 5" fill="none"/>`).join('')}<path d="${path}" stroke="#7a9a66" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((p,j)=>p?`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="var(--card)" stroke="#7a9a66" stroke-width="2"><title>${esc(dateText(items[j].started_at))}: ${items[j].network_score}</title></circle>`:`<circle cx="${x(j)}" cy="${H-5}" r="3" fill="#b8c0bb"><title>${esc(t('insufficient'))}</title></circle>`).join('')}</svg><div class="chart-axis">${items.map(h=>`<span>${esc(new Intl.DateTimeFormat(locale(),{day:'2-digit',month:'2-digit'}).format(new Date(h.started_at)))}</span>`).join('')}</div>`;
}
function historyView(){
  const H=state.history;
  return `${heading(t('history'),t('historySub'))}${scanBanner()}<div class="history-top"><section class="card chart-panel"><h2 class="card-title">${t('lastScans')}</h2><p class="subtitle">${t('trendNote')}</p>${chart()}</section><section class="card section-panel">${icon('chart',28)}<h2 class="section-title" style="margin-top:19px">${t('scopeReminder')}</h2><p class="subtitle" style="font-size:12px;line-height:1.9">${t('scopeReminderText')}</p><button class="text-button" style="margin-top:17px" data-action="learn-score">${t('learnMore')}${icon('arrow',14)}</button></section></div><section class="card" style="overflow:hidden"><div class="card-header"><h2 class="card-title">${t('history')}<span class="count-badge">${H.total}</span></h2></div><div class="history-filters"><label>${t('network')}<select id="hist-scope"><option value="">${t('allNetworks')}</option>${H.scopes.map(s=>`<option value="${esc(s.id)}" ${H.scope===s.id?'selected':''}>${esc(s.network_cidr)}${s.gateway?' · '+esc(s.gateway):''}</option>`).join('')}</select></label><label>${t('from')}<input type="date" id="hist-from" value="${esc(H.from)}"></label><label>${t('to')}<input type="date" id="hist-to" value="${esc(H.to)}"></label></div><div class="table-scroll"><table class="history-table"><thead><tr>${['date','profile','deviceCount','score','coverage','result'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody>${H.items.map(h=>`<tr><td><div class="history-date">${dateText(h.started_at)}</div><span class="history-time">${timeText(h.started_at)} · ${esc(h.network_cidr)}</span></td><td>${t(h.profile_id)}<div class="history-time">${h.port_count} TCP</div></td><td>${h.hosts_responded}</td><td><div class="mini-score">${h.network_score??'—'}<span><i style="width:${h.network_score??0}%"></i></span></div>${h.network_score==null&&h.network_state?`<div class="history-time">${t(h.network_state==='insufficient_coverage'?'insufficient':'notEvaluable')}</div>`:''}${h.provisional&&h.network_score!=null?`<div class="history-time">${t('provisional')}</div>`:''}</td><td>${pct(h.coverage)}</td><td><span class="risk-chip ${h.state==='completed'?'ok':['running','queued','cancelling'].includes(h.state)?'unknown':'medium'}"><span class="status-dot"></span>${stateLabel(h.state)}</span></td><td><button class="table-open" data-history="${esc(h.id)}" aria-label="${t('scanDetails')}">${icon('chevron',15)}</button></td></tr>`).join('')}</tbody></table>${H.items.length?'':`<div class="empty-state">${t('noScans')}</div>`}</div>${H.items.length<H.total?`<div class="table-foot"><button class="btn btn-secondary" data-action="more-history">${t('loadMore')}</button><span></span></div>`:''}</section>`;
}
function faqHtml(){const q=state.guideQuery.toLocaleLowerCase(locale());const items=state.guide.faq.map((f,i)=>({f,i})).filter(({f})=>!q||(f.q+' '+f.a).toLocaleLowerCase(locale()).includes(q));return items.map(({f,i})=>`<details class="faq-item" id="faq-${i}"><summary><span class="faq-number">${String(i+1).padStart(2,'0')}</span>${esc(f.q)}${icon('down',15)}</summary><div class="faq-answer">${esc(f.a)}</div></details>`).join('')||`<div class="empty-state">${t('noGuideResult')}</div>`;}
function guideView(){const tip=state.guide.tips[state.tipIndex]||'';return `${heading(t('guide'),t('guideSub'))}<div class="guide-grid"><section class="card guide-intro">${icon('book',33)}<h2>${t('guideIntro')}</h2><p>${t('guideIntroText')}</p><div class="guide-categories">${['TCP','UDP','LAN','MAC','RDP','Telnet'].map(k=>`<button data-guide-search="${k}">${k}</button>`).join('')}</div></section><section class="card section-panel"><div class="eyebrow">${t('tipLabel')}</div><div style="margin:16px 0 18px;color:#8aa76e">${icon('spark',34)}</div><p style="font-size:16px;color:var(--ink);line-height:1.75;max-width:430px">${esc(tip)}</p><button class="text-button" style="margin-top:14px" data-action="next-tip">${t('nextTip')}${icon('arrow',13)}</button></section></div><div style="margin-top:27px"><label class="search guide-search">${icon('search',18)}<input id="guide-search" value="${esc(state.guideQuery)}" placeholder="${t('searchGuide')}" aria-label="${t('searchGuide')}"></label><div class="faq-list" id="faq-list">${faqHtml()}</div></div><section class="card section-panel" style="margin-top:27px"><h2 class="section-title">${t('rulesTitle')} <span class="tag">${esc(state.caps?.ruleset_version||'')}</span></h2><p class="subtitle">${t('rulesNote')}</p><div class="table-scroll"><table class="rules-table"><thead><tr><th>${t('rule')}</th><th>${t('result')}</th><th>${t('severity')}</th><th>${t('penalty')}</th></tr></thead><tbody>${state.rulesList.map(r=>`<tr><td><strong>${esc(r.id)}</strong></td><td>${esc(r.title)}<div class="history-time">${esc(r.meaning)}</div></td><td>${t(r.severity==='info'?'informational':r.severity)}</td><td>${r.penalty}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settingsView(){
  const advText=t('advEngineAbout');
  return `${heading(t('settings'),t('settingsSub'))}<div class="settings-grid"><section class="card settings-card"><div class="settings-group"><h3>${t('language')}</h3><p>${t('languageText')}</p><div class="choice-row">${[['en','English'],['tr','Türkçe'],['de','Deutsch']].map(([v,txt])=>`<button class="choice-button ${state.lang===v?'selected':''}" data-language="${v}" aria-pressed="${state.lang===v}">${icon('globe',16)}${txt}${state.lang===v?icon('check',14):''}</button>`).join('')}</div></div><div class="settings-group"><h3>${t('appearance')}</h3><p>${t('appearanceText')}</p><div class="choice-row">${[['light','sun'],['dark','moon']].map(([v,i])=>`<button class="choice-button ${state.theme===v?'selected':''}" data-theme-choice="${v}" aria-pressed="${state.theme===v}">${icon(i,16)}${t(v)}</button>`).join('')}</div></div><div class="settings-group"><h3>${t('defaultProfile')}</h3><p>${t('defaultProfileText')}</p><select id="profile-select" class="setting-select" aria-label="${t('defaultProfile')}">${['quick','standard','custom'].map(v=>`<option value="${v}" ${state.defaultProfile===v?'selected':''}>${t(v)}</option>`).join('')}</select></div><div class="settings-group"><h3>${t('retention')}</h3><p>${t('retentionText')}</p><select id="retention-select" class="setting-select" aria-label="${t('retention')}">${['30','90','180','365','off'].map(v=>`<option value="${v}" ${state.retention===v?'selected':''}>${v==='off'?t('keepAll'):t('days',{n:v})}</option>`).join('')}</select></div><div class="settings-group toggle-row"><div><h3>${t('tipsEnabled')}</h3><p>${t('tipsEnabledText')}</p></div><button class="toggle ${state.tips?'on':''}" data-action="toggle-tips" role="switch" aria-checked="${state.tips}" aria-label="${t('tipsEnabled')}"><span></span></button></div><div class="settings-group"><h3>${t('dataTitle')}</h3><p>${t('dataText')}</p><div class="btn-row"><button class="btn btn-secondary" data-action="backup">${icon('database',15)}${t('backup')}</button><button class="btn btn-danger" data-action="delete-all">${icon('trash',15)}${t('deleteAll')}</button></div><p class="field-hint" style="margin-top:10px">${t('deleteAllText')}</p></div></section><aside class="card settings-card settings-side" style="align-self:start"><div class="about-mark"><img src="/favicon.svg" width="40" height="40" alt=""></div><div class="about-info"><strong>LANORA ${esc(state.caps?.app_version||'')}</strong>${t('aboutText')}</div><div class="about-tags"><span>TCP Connect</span><span>TR · EN · DE</span><span>Windows</span><span>${esc(state.caps?.ruleset_version||'')}</span><span>${esc(state.caps?.port_list_version||'')}</span></div><p class="settings-note">${t('aboutNote')}</p><p class="settings-note" style="margin-top:12px"><strong style="color:var(--ink)">${t('advancedEngine')}</strong><br>${esc(advText)}</p><p class="settings-note" style="margin-top:12px">${t('versions')}: ${esc(state.caps?.engine_version||'')}</p></aside></div>`;
}

function render(){
  if(state.fatal||!state.booted)return;
  const a=document.activeElement;const active=a?.id,selection=a?.selectionStart;
  document.documentElement.lang=state.lang;document.title='LANORA · '+t(state.view);document.body.dataset.theme=state.theme;document.getElementById('skip-link').textContent=t('skip');
  const g=badgeList().find(x=>x.key==='network_guardian');const gp=Math.min(3,g?.b.progress||0);
  const prio=allPrio().length;
  document.getElementById('app').innerHTML=`<div class="menu-overlay ${state.menu?'visible':''}" data-action="menu"></div><aside class="sidebar ${state.menu?'open':''}" aria-label="${t('workspace')}"><div class="brand"><span class="brand-symbol"><img src="/favicon.svg" width="40" height="40" alt=""></span><div><div class="brand-word">LANORA</div><div class="brand-tag">${t('tagline')}</div></div></div><div class="nav-label">${t('workspace')}</div><nav class="nav">${[['overview','grid'],['devices','devices'],['map','map'],['history','history'],['guide','book'],['settings','settings']].map(([v,i])=>`<button class="nav-btn ${state.view===v?'active':''}" data-view="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i,18)}${t(v)}${v==='devices'&&hosts().length?`<span class="nav-count">${hosts().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><button class="journey" data-action="badges" style="text-align:left"><div class="journey-icon">${icon('trophy',29)}</div><div class="journey-title">${t('guardian')}</div><p>${t('journeyText')}</p><div class="journey-bar"><span style="width:${gp/3*100}%"></span></div><div class="journey-foot"><span>${t('journeyProgress',{n:gp})}</span><span>${icon('arrow',12)}</span></div></button><div class="sidebar-footer"><span class="led"></span>${t('localDesign')}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="${t('menu')}">${icon('menu',19)}</button>${icon('grid',14)}<span>${esc(scan()?.network_cidr||'LANORA')}</span><span class="slash">/</span><strong>${t(state.view)}</strong></div><div class="top-actions"><span class="demo-label">${t('localMode')}</span><select class="lang-select" id="lang-select" aria-label="${t('language')}">${LANGS.map(l=>`<option value="${l}" ${l===state.lang?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select><span class="top-separator"></span><button class="icon-button" data-action="notifications" aria-label="${t('notifications')}">${icon('bell',18)}</button><span class="avatar" aria-hidden="true">${prio||'L'}</span></div></header><main class="main" id="main" tabindex="-1">${({overview,devices:devicesView,map:mapView,history:historyView,guide:guideView,settings:settingsView})[state.view]()}<footer class="footer"><span class="footer-left">${icon('shield',11)}${t('footerNote')}</span><span>LANORA ${esc(state.caps?.app_version||'')} · ${esc(state.caps?.ruleset_version||'')}</span></footer></main></div>`;
  if(active){const target=document.getElementById(active);if(target&&(target.tagName==='INPUT')){target.focus({preventScroll:true});try{target.setSelectionRange(selection,selection);}catch{}}}
}
async function setView(v){state.view=v;state.query='';state.filter='all';state.guideQuery='';state.menu=false;if(v==='history')await loadHistory(true).catch(()=>{});render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main')?.focus({preventScroll:true});}
async function loadHistory(reset){const H=state.history;if(reset)H.page=1;const q=new URLSearchParams({page:String(H.page),page_size:'25'});if(H.scope)q.set('network_scope_id',H.scope);if(H.from)q.set('from',H.from);if(H.to)q.set('to',H.to);const r=await api('GET','/scans?'+q);H.items=reset?r.items:[...H.items,...r.items];H.total=r.total;H.scopes=r.scopes;}

/* ---------- Pencereler ---------- */
function modalHead(title,sub){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="icon-button" data-action="close-modal" aria-label="${t('close')}">${icon('close',19)}</button></div>`;}
function showModal(html,wide=false){const el=document.getElementById('modal');el.className='modal'+(wide?' wide':'');el.innerHTML=html;el.setAttribute('aria-labelledby','modal-title');if(!el.open)el.showModal();}
function closeModal(){const el=document.getElementById('modal');if(el.open)el.close();}

function selectableAdapters(){return state.interfaces.filter(a=>a.selectable);}
function defaultAdv(){return {technique:'connect',portScope:'top',topPorts:100,portsText:'22,80,443',udpText:'53,123,161',udp:false,os:true,traceroute:false,serviceChecks:false,targetMode:'local',customTargets:'',authorized:false,reverseDns:true};}
function defaultForm(){const a=selectableAdapters()[0];return {interfaceId:a?.id||'',range:a?.suggested_range||'',targetsText:'',profile:state.defaultProfile||'quick',portsText:'',adv:defaultAdv(),preview:null,advPreview:null,error:null,busy:false};}
function formAdapter(){return state.interfaces.find(a=>a.id===state.scanForm.interfaceId);}
function advReady(){return !!state.caps?.advanced;}
function advTechniques(){return state.caps?.advanced?.techniques||['connect','udp'];}
function parsePorts(text){const out=new Set();for(const part of text.split(/[\s,;]+/).filter(Boolean)){const m=/^(\d{1,5})(?:-(\d{1,5}))?$/.exec(part);if(!m)throw Object.assign(new Error('PORT_INVALID'),{code:'PORT_INVALID'});const a=+m[1],b=m[2]?+m[2]:a;if(a<1||b>65535||b<a)throw Object.assign(new Error('PORT_INVALID'),{code:'PORT_INVALID'});if(b-a>1024)throw Object.assign(new Error('PORT_LIMIT'),{code:'PORT_LIMIT'});for(let p=a;p<=b;p++)out.add(p);}return [...out];}
function scanRequest(){const f=state.scanForm;const targets=f.range==='custom'?f.targetsText.split(/[\s,;]+/).filter(Boolean):[f.range];const req={interface_id:f.interfaceId,targets,profile_id:f.profile,include_udp:false,include_os_detection:false};if(f.profile==='custom')req.tcp_ports=parsePorts(f.portsText);return req;}
function advRequest(){const f=state.scanForm,v=f.adv;const targets=v.targetMode==='custom'?v.customTargets.split(/[\s,;\n]+/).filter(Boolean):[f.range];const req={interface_id:v.targetMode==='custom'?null:f.interfaceId,targets,technique:v.technique,include_udp:v.udp,port_scope:v.portScope,service_version:true,os_detection:v.os,traceroute:v.traceroute,reverse_dns:v.reverseDns,service_checks:v.serviceChecks,authorized:v.authorized};if(v.portScope==='top')req.top_ports=+v.topPorts||100;if(v.portScope==='custom'){req.tcp_ports=parsePorts(v.portsText);if(v.udp)req.udp_ports=parsePorts(v.udpText);}return req;}
function openScan(){if(state.active)return;state.scanForm=state.scanForm&&formAdapter()?{...state.scanForm,preview:null,advPreview:null,error:null,busy:false}:defaultForm();renderScanModal();}
function renderScanModal(){
  const f=state.scanForm;const a=formAdapter();const adapters=state.interfaces;const adv=state.caps?.advanced;
  const profiles=[['quick','quickDesc','~ 800 ms'],['standard','standardDesc','~ 1000 ms'],['custom','customDesc',''],['advanced','advancedDesc',t('advancedEngine')]];
  const isAdv=f.profile==='advanced';
  showModal(`${modalHead(t('scanTitle'),t('scanSubtitle'))}<div class="modal-body">${selectableAdapters().length?'':`<div class="error-box">${t('noNetwork')}</div>`}${!isAdv||f.adv.targetMode==='local'?`<label class="field-label" for="network-select">${t('network')}</label><select id="network-select" class="field-input">${adapters.map(x=>`<option value="${esc(x.id)}" ${x.id===f.interfaceId?'selected':''} ${x.selectable?'':'disabled'}>${esc(t('kind_'+x.kind))} · ${esc(x.name)} · ${esc(x.ip)}/${x.prefix_length} · ${esc(x.network_cidr)}${x.is_default_route?' · '+t('defaultRoute'):''}${x.selectable?'':' · '+t('notSelectable')}</option>`).join('')}</select>${a?`<p class="field-hint">${t('realNetwork',{cidr:a.network_cidr,n:num(a.address_count)})}</p>`:''}${a&&!isAdv?`<label class="field-label" for="range-select">${t('range')}</label><select id="range-select" class="field-input">${a.ranges.map(r=>`<option value="${esc(r)}" ${f.range===r?'selected':''}>${esc(r)}</option>`).join('')}<option value="custom" ${f.range==='custom'?'selected':''}>${t('customTargets')}</option></select>${f.range==='custom'?`<textarea id="targets-input" class="field-textarea" style="margin-top:8px" aria-label="${t('customTargets')}" spellcheck="false">${esc(f.targetsText)}</textarea><p class="field-hint">${t('customTargetsHint')}</p>`:''}`:''}`:''}<div class="field-label">${t('profile')}</div>${profiles.map(([v,d,time])=>`<label class="profile-option ${f.profile===v?'selected':''}"><input type="radio" name="scan-profile" value="${v}" ${f.profile===v?'checked':''}><span><span class="profile-title">${t(v)}</span><span class="profile-desc">${t(d)}${v==='advanced'?' · '+esc(time):''}</span></span><span class="profile-time">${v!=='advanced'?time:''}</span></label>`).join('')}${f.profile==='custom'?`<label class="field-label" for="ports-input">${t('customPorts')}</label><textarea id="ports-input" class="field-textarea" spellcheck="false">${esc(f.portsText)}</textarea><p class="field-hint">${t('customPortsHint')}</p>`:''}${isAdv?advBlock(f.adv,adv):''}${f.error?`<div class="error-box" role="alert">${esc(f.error)}</div>`:''}${!isAdv&&f.preview?previewBox(f.preview):''}${isAdv&&f.advPreview?advPreviewBox(f.advPreview):''}<p class="modal-note">${icon('info',15)}<span>${isAdv?t('advNote'):t('scanNote')}</span></p><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">${t('cancel')}</button><button class="btn btn-secondary" data-action="preview-scan" ${!f.busy&&(isAdv||a)?'':'disabled'}>${t('previewTargets')}</button><button class="btn btn-primary" data-action="begin-scan" ${!f.busy&&(isAdv||a)?'':'disabled'}>${icon('scan',15)}${t('beginScan')}</button></div></div>`,true);
}
function previewBox(p){return `<div class="info-box"><strong>${t('previewResult',{n:p.targets.length,ports:p.port_count,max:num(p.max_attempts)})}</strong><div class="ip-list">${p.targets.map(esc).join(', ')}</div>${p.excluded.length?`<div class="field-hint">${t('excluded',{list:p.excluded.map(esc).join(', ')})}</div>`:''}<div class="field-hint">${icon('check',11)} ${t('noElevation')}</div></div>`;}
function advBlock(v,adv){const techs=advTechniques();
  return `<div class="info-box" style="margin-bottom:12px">${icon('shield',14)} ${t('advEngineHint')}</div>
  <div class="field-label">${t('advTargets')}</div><div class="choice-row" style="margin-bottom:10px">${[['local','advLocal'],['custom','advCustom']].map(([k,l])=>`<button type="button" class="choice-button ${v.targetMode===k?'selected':''}" data-adv="targetMode" data-val="${k}">${t(l)}</button>`).join('')}</div>${v.targetMode==='custom'?`<textarea id="adv-targets" class="field-textarea" spellcheck="false" placeholder="example.com, 192.0.2.10, 198.51.100.0/28">${esc(v.customTargets)}</textarea><p class="field-hint">${t('advCustomHint')}</p><label class="check-row" style="margin-top:8px;align-items:flex-start"><input type="checkbox" id="adv-authorized" ${v.authorized?'checked':''}><span>${t('authorize')}</span></label>`:''}
  <div class="field-label">${t('technique')}</div><select id="adv-technique" class="field-input">${techs.map(x=>`<option value="${x}" ${v.technique===x?'selected':''}>${t('tech_'+x)}</option>`).join('')}</select>
  <div class="field-label">${t('portScope')}</div><div class="choice-row">${[['top','portTop'],['custom','portCustom'],['all','portAll']].map(([k,l])=>`<button type="button" class="choice-button ${v.portScope===k?'selected':''}" data-adv="portScope" data-val="${k}">${t(l)}</button>`).join('')}</div>${v.portScope==='top'?`<input id="adv-topports" class="field-input" style="margin-top:8px" type="number" min="1" max="65535" value="${v.topPorts}" aria-label="${t('portTop')}">`:''}${v.portScope==='custom'?`<input id="adv-ports" class="field-input" style="margin-top:8px" value="${esc(v.portsText)}" aria-label="${t('customPorts')}" placeholder="22,80,443,8000-8010">${v.udp?`<input id="adv-udpports" class="field-input" style="margin-top:6px" value="${esc(v.udpText)}" aria-label="UDP" placeholder="UDP: 53,123,161">`:''}`:''}${v.portScope==='all'?`<p class="field-hint">${t('portAllHint')}</p>`:''}
  <div class="field-label">${t('advOptions')}</div><div class="adv-toggles">${advToggle('udp','optUdp',v.udp)}${advToggle('os','optOs',v.os)}${advToggle('traceroute','optTrace',v.traceroute)}${advToggle('reverseDns','optRdns',v.reverseDns)}${advToggle('serviceChecks','optChecks',v.serviceChecks)}</div>
  ${v.serviceChecks?`<p class="field-hint">${icon('info',11)} ${t('checksHint')}</p>`:''}`;
}
function advToggle(key,label,on){return `<label class="check-row"><input type="checkbox" data-advtoggle="${key}" ${on?'checked':''}>${t(label)}</label>`;}
function advPreviewBox(p){const ext=p.targets.filter(t=>t.external);return `<div class="info-box"><strong>${t('advPreviewResult',{n:p.target_count,tech:t('tech_'+p.effective_technique)})}</strong><div class="field-hint">${t('portsPlan',{tcp:p.tcp_port_count,udp:p.udp_port_count})}</div><div class="ip-list">${p.targets.map(x=>esc(x.input)+(x.resolved&&x.resolved!==x.input?' → '+esc(x.resolved):'')+(x.external?' ⚠':'')).join(', ')}</div>${ext.length?`<div class="field-hint">${icon('alert',11)} ${t('externalWarn',{n:ext.length})}</div>`:''}${(p.os_detection||p.traceroute||p.udp||p.service_checks)?`<div class="field-hint">${[p.udp?'UDP':'',p.os_detection?t('optOs'):'',p.traceroute?t('optTrace'):'',p.service_checks?t('optChecks'):''].filter(Boolean).join(' · ')}</div>`:''}</div>`;}
function readScanInputs(){const f=state.scanForm;const ti=document.getElementById('targets-input');if(ti)f.targetsText=ti.value;const pi=document.getElementById('ports-input');if(pi)f.portsText=pi.value;const at=document.getElementById('adv-targets');if(at)f.adv.customTargets=at.value;const ap=document.getElementById('adv-ports');if(ap)f.adv.portsText=ap.value;const au=document.getElementById('adv-udpports');if(au)f.adv.udpText=au.value;const tp=document.getElementById('adv-topports');if(tp)f.adv.topPorts=tp.value;const az=document.getElementById('adv-authorized');if(az)f.adv.authorized=az.checked;}
async function previewScan(){readScanInputs();const f=state.scanForm;f.error=null;f.preview=null;f.advPreview=null;try{f.busy=true;if(f.profile==='advanced')f.advPreview=await api('POST','/advanced-scans/preview',advRequest());else f.preview=await api('POST','/scans/preview',scanRequest());}catch(e){f.error=errText(e);}finally{f.busy=false;renderScanModal();}}
async function beginScan(){
  readScanInputs();const f=state.scanForm;f.error=null;const advanced=f.profile==='advanced';
  try{f.busy=true;renderScanModal();
    const idem=crypto.randomUUID?crypto.randomUUID():String(Date.now());
    const r=advanced?await api('POST','/advanced-scans',advRequest(),{idem}):await api('POST','/scans',scanRequest(),{idem});
    closeModal();state.active=advanced?{scan_id:r.scan_id,state:'queued',engine:'advanced',phase:'advanced',phase_percent:0,hosts_responded:0}:{scan_id:r.scan_id,state:'queued',phase:'discovery',phase_index:1,phase_count:5,phase_done:0,phase_total:0,phase_percent:0,hosts_responded:0};render();subscribe(r.scan_id);
  }catch(e){f.error=errText(e);f.busy=false;renderScanModal();if(e.code==='SCAN_ACTIVE'){loadDashboard().then(()=>{if(state.dash.active){state.active=state.dash.active;subscribe(state.active.scan_id);render();}});}}
}
async function stopScan(){if(!state.active)return;try{await api('POST',`/scans/${encodeURIComponent(state.active.scan_id)}/cancel`,{});state.active.state='cancelling';updateBanner();}catch(e){toast(errText(e));}}

function openReport(scanId){
  const id=scanId||scan()?.id;if(!id){toast(t('noScanForReport'));return;}
  state.report.scanId=id;state.report.lang=state.report.lang||state.lang;renderReportModal();
}
function renderReportModal(){
  const R=state.report;const s=state.history.items.find(x=>x.id===R.scanId)||(scan()?.id===R.scanId?scan():null);
  showModal(`${modalHead(t('reportTitle'),t('reportSubtitle'))}<div class="modal-body">${s?`<p class="field-hint">${t('reportScan',{date:dateText(s.started_at)+' '+timeText(s.started_at),state:stateLabel(s.state)})}</p>`:''}<div class="report-choice">${[['pdf','file','PDF','pdfDescription'],['xlsx','sheet','Excel · .xlsx','excelDescription']].map(([v,i,title,desc])=>`<button class="report-option ${R.format===v?'selected':''}" data-report="${v}" aria-pressed="${R.format===v}">${icon(i,29)}<strong>${title}</strong><span>${t(desc)}</span></button>`).join('')}</div><label class="field-label" for="report-lang">${t('reportLang')}</label><select id="report-lang" class="field-input">${[['en','English'],['tr','Türkçe'],['de','Deutsch']].map(([v,n])=>`<option value="${v}" ${R.lang===v?'selected':''}>${n}</option>`).join('')}</select><p class="modal-note">${icon('info',15)}<span>${t('scoreHelp')}</span></p><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">${t('cancel')}</button><button class="btn btn-primary" data-action="export">${icon('download',15)}${t('download')}</button></div></div>`);
}
async function exportReport(){
  const R=state.report;const btn=document.querySelector('[data-action="export"]');if(btn)btn.disabled=true;
  try{const r=await api('GET',`/scans/${encodeURIComponent(R.scanId)}/report?format=${R.format}&lang=${R.lang}`,null,{raw:true});
    const blob=await r.blob();const cd=r.headers.get('content-disposition')||'';const m=/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(cd);const name=m?decodeURIComponent(m[1]):`LANORA.${R.format}`;
    const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);closeModal();toast(t('reportReady',{file:name}));
  }catch(e){toast(errText(e));if(btn)btn.disabled=false;}
}
function openBadges(){showModal(`${modalHead(t('badgeDetails'),t('badgeDescription'))}<div class="modal-body">${badgeList().map(x=>`<div class="detail-callout"><h3>${icon(x.i,20)}${t(x.k)}<span class="risk-chip ${x.b.earned?(x.b.active?'ok':'medium'):'unknown'}" style="margin-left:auto">${x.b.earned?(x.b.active?t('earned'):t('badgeInactive')):t('locked')}</span></h3><p>${esc(badgeNote(x))}</p></div>`).join('')}<div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">${t('close')}</button></div></div>`);}
async function openHistory(id){
  const s=state.history.items.find(x=>x.id===id);if(!s)return;
  let cmp=null;try{cmp=await api('GET',`/scans/${encodeURIComponent(id)}/compare`);}catch{}
  const cmpHtml=!cmp||!cmp.previous_scan_id?`<p class="field-hint">${t('compareNone')}</p>`:`<p class="field-hint">${cmp.compatible?t('compareCompatible'):t('compareIncompatible',{list:cmp.mismatches.map(m=>t('mm_'+m)).join(', ')})}</p><div class="compare-list">${cmp.devices.filter(d=>d.status!=='unchanged').map(d=>`<div class="compare-item"><strong>${esc(d.label||(d.vendor?shortVendor(d.vendor):t('unknownDevice')))}</strong> · ${esc(d.ip_after||d.ip_before||'')} · ${t('dev_'+d.status)}${cmp.compatible&&d.score_before!==d.score_after?` · ${d.score_before??'—'} → ${d.score_after??'—'}`:''}${changeChips(d.newly_opened,d.closed_with_evidence,d.no_longer_responding,d.not_measured)}</div>`).join('')||`<div class="compare-item">${t('dev_unchanged')}</div>`}</div>`;
  showModal(`${modalHead(t('scanDetails'),dateText(s.started_at)+' · '+timeText(s.started_at)+' · '+esc(s.network_cidr))}<div class="modal-body"><div class="modal-summary"><div><strong>${s.network_score??'—'}</strong><span>${t('score')}${s.provisional&&s.network_score!=null?' · '+t('provisional'):''}</span></div><div><strong>${s.hosts_responded}</strong><span>${t('devices')}</span></div><div><strong>${pct(s.coverage)}</strong><span>${t('coverage')}</span></div></div><div class="detail-callout"><h3>${t(s.profile_id)} · ${stateLabel(s.state)}${s.reason_code?' · '+esc(reasonLabel(s.reason_code)):''}</h3><p>${s.port_count} TCP · ${t('probedNote',{probed:s.addresses_probed})} · ${t('priorityFindings')}: ${s.priority_findings}<br>${t('versions')}: ${esc(s.engine_version)} · ${esc(s.ruleset_version)} · ${esc(s.port_list_version||'')}</p></div><h3 class="section-title" style="font-size:13px">${t('compare')}</h3>${cmpHtml}<div class="modal-actions"><button class="btn btn-danger" data-action="delete-scan" data-id="${esc(s.id)}" ${['running','queued','cancelling'].includes(s.state)?'disabled':''}>${icon('trash',14)}${t('deleteScan')}</button><button class="btn btn-secondary" data-action="report-for" data-id="${esc(s.id)}" ${['running','queued','cancelling'].includes(s.state)?'disabled':''}>${icon('download',14)}${t('downloadReport')}</button><button class="btn btn-primary" data-action="close-modal">${t('close')}</button></div></div>`,true);
}
function changeChips(n=[],c=[],s=[],m=[]){const chips=[...n.map(p=>`<span class="change-chip new">${icon('alert',9)} ${t('history_new')} ${p}</span>`),...c.map(p=>`<span class="change-chip closed">${t('history_closed')} ${p}</span>`),...s.map(p=>`<span class="change-chip">${t('history_silent')} ${p}</span>`),...m.map(p=>`<span class="change-chip">${t('history_notmeasured')} ${p}</span>`)];return chips.length?`<div class="change-chips">${chips.join('')}</div>`:'';}
function confirmModal(title,text,action,label,data=''){showModal(`${modalHead(title,text)}<div class="modal-body"><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">${t('cancel')}</button><button class="btn btn-danger" data-action="${action}" ${data}>${label}</button></div></div>`);}

/* ---------- Device panel ---------- */
function findHost(id){return hosts().find(h=>String(h.id)===String(id));}
async function openDevice(hostId,tab='general'){
  const h=findHost(hostId);if(!h)return;
  state.device={hostId:h.id,tab,renaming:false,detail:null};renderDevice();
  const el=document.getElementById('device-panel');if(!el.open)el.showModal();
  if(h.device_id){try{state.device.detail=await api('GET','/devices/'+encodeURIComponent(h.device_id));renderDevice();}catch{}}
}
function evidenceText(h){return (h.discovery_evidence||'').split(',').filter(Boolean).map(e=>M['ev_'+e]?t('ev_'+e):e).join(', ')||'—';}
function advEvidence(h){
  const scripts=h.scripts||[],trace=h.trace||[];let out='';
  if(scripts.length)out+=`<div style="margin-top:18px"><div class="finding-heading">${icon('shield',16)}<h3 class="card-title" style="font-size:12px">${t('hostScripts')}</h3></div>${scripts.map(s=>`<div class="script-item"><strong>${esc(s.id||'')}</strong><pre>${esc(s.output||'')}</pre></div>`).join('')}</div>`;
  if(trace.length)out+=`<div style="margin-top:18px"><div class="finding-heading">${icon('map',16)}<h3 class="card-title" style="font-size:12px">${t('traceroute')}</h3></div><div class="trace-list">${trace.map(traceHopHtml).join('')}</div></div>`;
  return out;
}
/* API contract is snake_case: { ttl, ip, host, rtt_ms } (F15). */
function traceHopHtml(hp){const rtt=hp.rtt_ms;return `<div class="trace-hop"><span class="trace-ttl">${esc(hp.ttl)}</span><span class="trace-ip">${esc(hp.ip||'*')}</span>${hp.host&&hp.ip?`<span style="color:var(--muted)">${esc(hp.host)}</span>`:''}${rtt!=null?`<span class="trace-rtt">${esc(rtt)} ms</span>`:''}</div>`;}
function osText(h){return h.os_candidate?`${esc(h.os_candidate)} · ${t('estimated')} (${(h.os_source||'').split('+').map(x=>M['src_'+x]?t('src_'+x):esc(x)).join(' + ')}, ${t('conf_'+h.os_confidence)})`:t('unknown');}
function vendorText(h){return h.vendor?esc(h.vendor):h.mac?(h.mac_kind==='local_admin'?t('randomMac'):t('unknown')):t('unknown');}
function stateCls(s){return s==='open'?'st-open':s==='closed'?'st-closed':'st-unknown';}
function findingBlock(h,f){
  const r=state.rules[f.rule_id];if(!r)return '';const fill=s=>esc(String(s||'').replace('{port}',f.port).replace('{count}',f.uncertain_count??0));
  const canFlag=h.device_id&&f.port>0&&(f.severity==='high'||f.severity==='medium');
  return `<details class="finding-block ${f.severity}" ${f.severity==='high'?'open':''}><summary>${icon(f.severity==='info'?'info':'alert',14)}${esc(f.rule_id)} · ${esc(r.title)}<span class="risk-chip sev ${f.severity==='high'?'high':f.severity==='medium'?'medium':'unknown'}">${t(f.severity==='info'?'informational':f.severity)}${f.penalty?` · −${f.penalty}`:''}</span></summary><div class="finding-sections"><div><h4>${t('whatObserved')}</h4><p>${fill(r.observed)}</p>${f.evidence?`<p class="evidence">${esc(f.evidence)}</p>`:''}</div><div><h4>${t('whatMeans')}</h4><p>${fill(r.meaning)}</p></div><div><h4>${t('whatDo')}</h4><p>${fill(r.action)}</p></div><div><h4>${t('howVerify')}</h4><p>${fill(r.verify)}</p></div>${canFlag?`<label class="check-row"><input type="checkbox" data-required="${f.port}" ${f.required?'checked':''}>${t('markRequired')}</label>`:''}</div></details>`;
}
function renderDevice(){
  const D=state.device;if(!D)return;const h=findHost(D.hostId);if(!h)return;const det=D.detail;
  const el=document.getElementById('device-panel');el.setAttribute('aria-labelledby','device-title');
  const counts=h.state_counts||{};const open=counts.open||0,closed=counts.closed||0,silent=(counts.no_response||0)+(counts.filtered||0)+(counts.open_filtered||0),other=(counts.not_tested||0)+(counts.error||0);
  const prio=prioFindings(h);
  const general=`<div class="detail-grid">${[['manufacturer',vendorText(h)],['os',osText(h)],['macAddress',h.mac?esc(h.mac):t('macMissing')],['discoveryEvidence',esc(evidenceText(h))],['lastSeen',`${dateText(det?.last_seen||h.device_last_seen)} ${timeText(det?.last_seen||h.device_last_seen)}<div class="field-hint">${t('lastSeenNote')}</div>`],['firstSeen',`${dateText(det?.first_seen||h.device_first_seen)}`],['hostScore',h.score!=null?h.score+' / 100':t('insufficient')+(h.penalty?` (≤ ${h.raw_score})`:'')],['coverage',`${pct(h.coverage)} (${h.definite_pairs}/${h.planned_pairs})`],...(h.hostname?[['hostname',esc(h.hostname)+(h.hostname_type?` (${esc(h.hostname_type)})`:'')]]:[]),...(h.ipv6?[['ipv6Addr',esc(h.ipv6)]]:[]),...(h.distance!=null?[['networkDistance',t('hops',{n:h.distance})]]:[])].map(([k,v])=>`<div><div class="detail-label">${t(k)}</div><div class="detail-value">${v}</div></div>`).join('')}</div>${advEvidence(h)}<div class="detail-callout ${prio.length?'warn':''}"><h3>${icon(prio.length?'alert':'info',16)}${t(prio.length?'needsService':'informational')}</h3><p>${t(prio.length?'needsServiceText':'noPriorityText')}</p></div><button class="btn btn-secondary" data-device-tab="ports">${t('reviewPorts')}${icon('arrow',14)}</button><div class="detail-callout"><h3>${icon('info',14)}${t('identity')}</h3><p>${t('identity_'+h.identity_status)}</p>${det?`<div class="identity-row"><select id="merge-select" class="field-input" aria-label="${t('mergeWith')}"><option value="">${t('chooseDevice')}</option>${det.merge_candidates.map(c=>`<option value="${esc(c.id)}">${esc(c.name||t('unknownDevice'))} · ${esc(c.ip||'')} · ${esc(c.mac||'')}</option>`).join('')}</select><button class="btn btn-secondary" data-action="merge">${t('merge')}</button></div>${det.merged_devices.length?`<div class="btn-row" style="margin-top:8px">${det.merged_devices.map(m=>`<button class="btn btn-secondary" data-action="unmerge" data-id="${esc(m)}">${t('unmerge')}</button>`).join('')}</div>`:''}`:''}</div>`;
  const ports=`<div class="modal-summary" style="grid-template-columns:repeat(4,1fr)"><div><strong>${open}</strong><span>${t('st_open')}</span></div><div><strong>${closed}</strong><span>${t('st_closed')}</span></div><div><strong>${silent}</strong><span>${t('st_no_response')}</span></div><div><strong>${other}</strong><span>${t('st_not_tested')}</span></div></div><div class="port-list">${(h.open||[]).map(p=>{const f=(h.findings||[]).find(x=>x.port===p.port&&x.protocol===p.protocol);const sev=f?.severity||'info';return `<div class="port-item ${sev==='high'?'high':sev==='medium'?'medium':''}"><div class="port-item-top"><strong class="port-number">${p.port}</strong><span class="port-service">${p.protocol.toUpperCase()} · ${esc(p.service_name||t('unknown'))}${p.service_product?' · '+esc(p.service_product)+(p.service_version?' '+esc(p.service_version):''):''}</span><span class="port-state ${stateCls(p.state)}">${t('st_'+p.state)}</span></div><p>${t('evidenceBy',{m:t('m_'+(p.service_method||'port_table'))})}${p.evidence_summary?` — <span class="evidence" style="font-family:Consolas,monospace">${esc(p.evidence_summary)}</span>`:''}</p>${f?findingBlock(h,f):''}</div>`;}).join('')||`<div class="empty-state">${t('noOpenObserved')}</div>`}${(h.findings||[]).filter(f=>f.rule_id==='R08').map(f=>findingBlock(h,f)).join('')}</div><p class="panel-footer">${t('portDetailsNote')}</p>`;
  const hist=!det?`<div class="empty-state">${t('loading')}</div>`:`<h3 class="section-title">${t('deviceHistory')}</h3>${det.history.map(e=>`<div class="history-entry"><div class="history-entry-top"><div><div style="font-size:12px;color:var(--ink);margin-bottom:6px">${dateText(e.started_at)} · ${timeText(e.started_at)}</div><div style="font-size:10px;color:var(--muted)">${t(e.profile_id)} · ${esc(e.ip)} · ${stateLabel(e.scan_state)} · ${pct(e.coverage)}</div></div><span class="mini-score">${e.score!=null?e.score+' / 100':'—'}</span></div><div class="field-hint">${t('openList',{list:e.open_ports.length?e.open_ports.join(', '):t('none')})}</div>${changeChips(e.newly_opened,e.closed_with_evidence,e.no_longer_responding,e.not_measured)}</div>`).join('')||`<p class="field-hint">${t('noHistory')}</p>`}${det.label_history.length?`<h3 class="section-title" style="margin-top:22px">${t('labelHistory')}</h3>${det.label_history.map(l=>`<div class="history-entry"><div style="font-size:11px">${esc(l.old_name||'—')} → <strong>${esc(l.new_name||'—')}</strong>${l.new_type!==l.old_type?` · ${t('type_'+(l.new_type||'unknown'))}`:''}</div><div class="field-hint">${dateText(l.changed_at)} ${timeText(l.changed_at)}</div></div>`).join('')}`:''}`;
  el.innerHTML=`<div class="panel-top"><div class="panel-topline"><div class="panel-device-icon">${icon(hostIcon(h),31)}</div><button class="icon-button" data-action="close-device" aria-label="${t('close')}">${icon('close',20)}</button></div><h2 id="device-title">${esc(hostName(h))}${h.device_id?`<button class="icon-button" data-action="rename" aria-label="${t('rename')}">${icon('edit',14)}</button>`:''}</h2>${D.renaming?`<form class="rename-form" id="rename-form"><input class="field-input" id="rename-input" maxlength="80" required value="${esc(h.label||'')}" aria-label="${t('deviceName')}"><button class="btn btn-primary" type="submit">${t('save')}</button></form><select id="type-select" class="field-input type-select" aria-label="${t('deviceType')}">${DEVICE_TYPES.map(x=>`<option value="${x}" ${hostType(h)===x?'selected':''}>${t('type_'+x)}</option>`).join('')}</select>`:''}<div class="ip">${esc(h.ip)}<span style="color:var(--line)">·</span>${esc(h.vendor?shortVendor(h.vendor):t('unknown'))}<span style="color:var(--line)">·</span>${t('type_'+hostType(h))}</div>${riskChip(h)}</div><div class="panel-tabs" role="tablist" aria-label="${t('device')}">${['general','ports','deviceHistory'].map(k=>`<button class="panel-tab ${D.tab===k?'selected':''}" role="tab" aria-selected="${D.tab===k}" data-device-tab="${k}">${t(k)}</button>`).join('')}</div><div class="panel-content" role="tabpanel">${D.tab==='general'?general:D.tab==='ports'?ports:hist}</div>`;
  if(D.renaming){const input=document.getElementById('rename-input');input.focus();input.select();}
}
async function refreshAfterDeviceChange(deviceId){await loadDashboard();render();const h=hosts().find(x=>x.id===state.device?.hostId);if(state.device&&h){state.device.detail=h.device_id?await api('GET','/devices/'+encodeURIComponent(h.device_id)):null;renderDevice();}}

/* ---------- Olaylar ---------- */
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action],[data-view],[data-host],[data-filter],[data-language],[data-theme-choice],[data-report],[data-device-tab],[data-history],[data-guide-search],[data-adv]');
  if(!el||el.disabled)return;
  if(el.dataset.view){setView(el.dataset.view);return;}
  if(el.dataset.host){openDevice(el.dataset.host,el.dataset.tab||'general');return;}
  if(el.dataset.filter){state.filter=el.dataset.filter;render();return;}
  if(el.dataset.language){await changeLang(el.dataset.language);return;}
  if(el.dataset.themeChoice){state.theme=el.dataset.themeChoice;try{localStorage.setItem('lanora-theme',state.theme);}catch{}render();saveSettings({theme:state.theme}).catch(()=>{});return;}
  if(el.dataset.report){state.report.format=el.dataset.report;renderReportModal();return;}
  if(el.dataset.deviceTab){state.device.tab=el.dataset.deviceTab;state.device.renaming=false;renderDevice();return;}
  if(el.dataset.history){openHistory(el.dataset.history);return;}
  if(el.dataset.guideSearch){state.guideQuery=el.dataset.guideSearch;render();return;}
  if(el.dataset.adv){readScanInputs();state.scanForm.adv[el.dataset.adv]=el.dataset.val;state.scanForm.advPreview=null;state.scanForm.error=null;renderScanModal();return;}
  switch(el.dataset.action){
    case'menu':state.menu=!state.menu;render();break;
    case'scan':openScan();break;
    case'preview-scan':previewScan();break;
    case'begin-scan':beginScan();break;
    case'stop-scan':stopScan();break;
    case'close-modal':closeModal();break;
    case'close-device':document.getElementById('device-panel').close();break;
    case'report':openReport();break;
    case'report-for':openReport(el.dataset.id);break;
    case'export':exportReport();break;
    case'view-findings':state.filter='priority';render();document.getElementById('findings-card')?.scrollIntoView({behavior:'smooth',block:'center'});break;
    case'learn-port':openFaq(1);break;
    case'learn-score':openFaq(2);break;
    case'next-tip':state.tipIndex=(state.tipIndex+1)%Math.max(1,state.guide.tips.length);render();break;
    case'toggle-tips':state.tips=!state.tips;render();saveSettings({tips:state.tips}).then(()=>toast(t('saved'))).catch(e=>toast(errText(e)));break;
    case'badges':openBadges();break;
    case'more-history':state.history.page++;await loadHistory(false);render();break;
    case'notifications':{const n=allPrio().length;toast(n?t('notifFindings',{n}):t('noNotifications'));break;}
    case'rename':state.device.renaming=!state.device.renaming;renderDevice();break;
    case'merge':{const sel=document.getElementById('merge-select');const h=findHost(state.device.hostId);if(!sel?.value||!h?.device_id)break;try{await api('PATCH','/devices/'+encodeURIComponent(h.device_id),{merge_into:sel.value});toast(t('merged'));await refreshAfterDeviceChange();}catch(err){toast(errText(err));}break;}
    case'unmerge':try{await api('PATCH','/devices/'+encodeURIComponent(el.dataset.id),{unmerge:true});toast(t('unmerged'));await refreshAfterDeviceChange();}catch(err){toast(errText(err));}break;
    case'backup':try{const r=await api('POST','/data/backup',{});toast(t('backupDone',{file:r.file}));}catch(err){toast(errText(err));}break;
    case'delete-all':confirmModal(t('deleteAllConfirm'),t('deleteAllText'),'confirm-delete-all',t('deleteAll'));break;
    case'confirm-delete-all':try{await api('POST','/data/delete-all',{confirm:'DELETE_ALL'});closeModal();applySettings(await api('GET','/settings'));await loadLangContent();await loadDashboard();state.history={items:[],total:0,page:1,scopes:[],scope:'',from:'',to:''};render();toast(t('deleteAllDone'));}catch(err){toast(errText(err));}break;
    case'delete-scan':confirmModal(t('deleteScan'),t('deleteScanConfirm'),'confirm-delete-scan',t('deleteScan'),`data-id="${esc(el.dataset.id)}"`);break;
    case'confirm-delete-scan':try{await api('DELETE','/scans/'+encodeURIComponent(el.dataset.id),{});closeModal();await loadDashboard();await loadHistory(true);render();toast(t('scanDeleted'));}catch(err){toast(errText(err));}break;
  }
});
async function changeLang(l){if(!LANGS.includes(l)||l===state.lang)return;state.lang=l;try{await saveSettings({lang:l});await loadLangContent();}catch(e){toast(errText(e));}render();if(state.device&&document.getElementById('device-panel').open)renderDevice();}
function openFaq(i){setView('guide').then(()=>{const item=document.getElementById('faq-'+i);if(item){item.open=true;item.scrollIntoView({behavior:'smooth',block:'center'});item.querySelector('summary')?.focus();}});}
document.addEventListener('input',e=>{
  if(e.target.id==='device-search'){state.query=e.target.value;render();}
  if(e.target.id==='guide-search'){state.guideQuery=e.target.value;document.getElementById('faq-list').innerHTML=faqHtml();}
  if(e.target.id==='targets-input'&&state.scanForm){state.scanForm.targetsText=e.target.value;state.scanForm.preview=null;}
  if(e.target.id==='ports-input'&&state.scanForm){state.scanForm.portsText=e.target.value;state.scanForm.preview=null;}
});
document.addEventListener('change',async e=>{
  const id=e.target.id;
  if(id==='lang-select'){await changeLang(e.target.value);}
  else if(id==='retention-select'){try{await saveSettings({retention:e.target.value});toast(t('saved'));}catch(err){toast(errText(err));}}
  else if(id==='profile-select'){try{await saveSettings({default_profile:e.target.value});toast(t('saved'));}catch(err){toast(errText(err));}}
  else if(id==='network-select'){readScanInputs();const a=state.interfaces.find(x=>x.id===e.target.value);state.scanForm.interfaceId=e.target.value;state.scanForm.range=a?.suggested_range||'';state.scanForm.preview=null;state.scanForm.advPreview=null;state.scanForm.error=null;renderScanModal();}
  else if(id==='range-select'){readScanInputs();state.scanForm.range=e.target.value;state.scanForm.preview=null;state.scanForm.error=null;renderScanModal();}
  else if(e.target.name==='scan-profile'){readScanInputs();state.scanForm.profile=e.target.value;state.scanForm.preview=null;state.scanForm.advPreview=null;state.scanForm.error=null;renderScanModal();}
  else if(id==='adv-technique'){readScanInputs();state.scanForm.adv.technique=e.target.value;state.scanForm.advPreview=null;}
  else if(id==='adv-scripts'){readScanInputs();state.scanForm.adv.scripts=e.target.value;state.scanForm.advPreview=null;renderScanModal();}
  else if(id==='adv-timing'){readScanInputs();state.scanForm.adv.timing=e.target.value;}
  else if(e.target.dataset.advtoggle){readScanInputs();state.scanForm.adv[e.target.dataset.advtoggle]=e.target.checked;state.scanForm.advPreview=null;renderScanModal();}
  else if(id==='report-lang'){state.report.lang=e.target.value;}
  else if(id==='hist-scope'||id==='hist-from'||id==='hist-to'){const H=state.history;H.scope=document.getElementById('hist-scope').value;H.from=document.getElementById('hist-from').value;H.to=document.getElementById('hist-to').value;try{await loadHistory(true);}catch(err){toast(errText(err));}render();}
  else if(id==='type-select'){const h=findHost(state.device.hostId);if(!h?.device_id)return;try{await api('PATCH','/devices/'+encodeURIComponent(h.device_id),{user_type:e.target.value});toast(t('nameSaved'));await refreshAfterDeviceChange();state.device.renaming=true;renderDevice();}catch(err){toast(errText(err));}}
  else if(e.target.dataset.required){const h=findHost(state.device.hostId);if(!h?.device_id)return;try{await api('PUT',`/devices/${encodeURIComponent(h.device_id)}/services/tcp/${e.target.dataset.required}`,{required:e.target.checked});toast(t('saved'));await refreshAfterDeviceChange();}catch(err){toast(errText(err));}}
});
document.addEventListener('submit',async e=>{
  if(e.target.id!=='rename-form')return;e.preventDefault();
  const value=document.getElementById('rename-input').value.trim();if(!value||value.length>80){toast(t('nameError'));return;}
  const h=findHost(state.device.hostId);if(!h?.device_id)return;
  try{await api('PATCH','/devices/'+encodeURIComponent(h.device_id),{custom_name:value});state.device.renaming=false;toast(t('nameSaved'));await refreshAfterDeviceChange();}catch(err){toast(errText(err));}
});
for(const id of ['modal','device-panel']){const el=document.getElementById(id);el.addEventListener('click',e=>{if(e.target===el){const r=el.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el.close();}});}
document.getElementById('device-panel').addEventListener('close',()=>{state.device=null;});
boot().catch(e=>{console.error(e);if(!state.fatal)renderFatal();});
